-- Sample campaigns carried over from the design preview. They are marked "sample" so you can delete or replace them in /admin/campaigns.
CREATE TABLE IF NOT EXISTS uploads (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  kind TEXT NOT NULL,                 -- avatar | banner
  mime TEXT NOT NULL,                 -- image/jpeg | image/png | image/webp only
  size INTEGER NOT NULL,
  data TEXT NOT NULL,                 -- base64 of the re-encoded image
  created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS uploads_user ON uploads (user_id, kind);

INSERT OR IGNORE INTO campaigns (id, title, creator, type, cover_url, preview_url, platforms_json, rate_cents, budget_cents, ends_on, summary, clip_this_json, off_limits_json, status, admin_note, launched_at, created_at, updated_at)
VALUES ('red-room', 'Red Room', 'KXNG VALE', 'Music · Single', '/covers/01.jpg', '/previews/01.mp3', '["tiktok","instagram","youtube"]', 300, 5000000, 'Oct 30', 'New single out Friday. We want the hook in front of as many people as possible — clip the performance video, the studio session, or use the track under your own edits.', '["The chorus drop at 0:42 — it is the moment","Studio session footage from the drive folder","Your own edits using the official audio"]', '["Re-uploads of the full music video","Sped-up or pitched versions of the track","Anything referencing other artists by name"]', 'live', 'sample', 1760054400, 1760054400, 1760054400);
INSERT OR IGNORE INTO campaigns (id, title, creator, type, cover_url, preview_url, platforms_json, rate_cents, budget_cents, ends_on, summary, clip_this_json, off_limits_json, status, admin_note, launched_at, created_at, updated_at)
VALUES ('mercury', 'Mercury', 'Hollow Form', 'Music · Album', '/covers/02.jpg', '/previews/02.mp3', '["tiktok","youtube"]', 250, 3000000, 'Nov 12', 'A 10-track electronic album. Pick your favourite track and build a visual around it. Slow, heavy, cinematic edits perform best.', '["Any track from the album, full or looped","Visualizer footage supplied in the brief pack","Reaction or first-listen formats"]', '["Tracks under 5 seconds","Brand logos in frame","AI voice-overs"]', 'live', 'sample', 1760054400, 1760054400, 1760054400);
INSERT OR IGNORE INTO campaigns (id, title, creator, type, cover_url, preview_url, platforms_json, rate_cents, budget_cents, ends_on, summary, clip_this_json, off_limits_json, status, admin_note, launched_at, created_at, updated_at)
VALUES ('late-shift', 'Late Shift', 'Dex Marlow', 'Streamer · Highlights', '/covers/03.jpg', '/previews/03.mp3', '["tiktok","youtube","instagram"]', 180, 2400000, 'Oct 15', 'Dex streams five nights a week. Find the moments — rage quits, clutch plays, the chat going wild — and cut them tight.', '["Clutch plays and fails from any VOD this month","Funny chat interactions with captions","Vertical crops with facecam on top"]', '["Clips older than 30 days","Sponsor segments","Anything from private Discord calls"]', 'live', 'sample', 1760054400, 1760054400, 1760054400);
