VALUES ('concrete', 'Concrete', 'Parkline Skate Co.', 'Brand · Launch', '/covers/05.jpg', '/previews/05.mp3', '["tiktok","instagram","youtube"]', 200, 2000000, 'Dec 01', 'Our new deck line drops this month. Clip the team edit, or film your own session with a Parkline deck in shot.', '["Tricks from the official team edit","Your own skate footage with the deck visible","Slow-motion landings"]', '["Competitor brands in frame","Unsafe street stunts","Music without a licence"]', 'live', 'sample', 1760054400, 1760054400, 1760054400);
