VALUES ('wax', 'Wax', 'Juno Park', 'Music · Album', '/covers/10.jpg', '/previews/10.mp3', '["tiktok","youtube"]', 320, 3200000, 'Dec 14', 'A warm, strange debut record. Art-school energy. Surreal visuals, textures and slow edits sit best with the sound.', '["Any album track under your own visuals","Vinyl unboxing","Stop-motion or collage formats"]', '["Low-effort lyric slideshows","Stolen artwork","Sped-up audio"]', 'live', 'sample', 1760054400, 1760054400, 1760054400);

